"""作业 4：根据用户截图转录题目并独立解答；无官方答案。"""
def get_questions(p, f, ul):
    return [
    (4,1,'蒙特卡洛策略评估的特点','下列关于蒙特卡洛策略评估的说法，哪个是错误的？',
    ['蒙特卡洛方法适用于非马尔可夫场景','蒙特卡洛方法不要求回合在有限步数内结束','蒙特卡洛方法只抽样了部分轨迹，相比动态规划训练速度更快','蒙特卡洛方法基于大数定律'],1,
    '<p class="note">建议答案：B。按本课程的经典完整回合 MC 语境判断；原题 C 把速度优势写成无条件结论，也不够严谨。这是根据题目与课程定义作出的解答，未提供官方答案。</p>' +
    p('蒙特卡洛（Monte Carlo，MC）策略评估从完整回合中取得实际回报，再对回报样本求平均。若回合一直不结束，就无法按经典算法取得完整的有限回合回报。因此 B 与本题使用的算法前提相矛盾。') +
    f('G<sub>t</sub> = ∑<sub>k=0</sub><sup>T−t−1</sup> γ<sup>k</sup>R<sub>t+k+1</sub><br>V(s) ≈ (1 / N(s)) ∑<sub>i=1</sub><sup>N(s)</sup> G<sup>(i)</sup>(s)') +
    p('T 为终止时刻，N(s) 为纳入统计的回报样本数。需要实际采集的回合有限结束，并不意味着所有回合必须具有相同长度或统一的固定步数上限。') +
    ul('<b>A：可按课程语境接受。</b> MC 直接平均完整回报，不依赖当前状态与后继价值之间的 Bellman 自举关系，因此可用于某些非马尔可夫观测下的回报估计。但这不保证仅用当前观测就能表示最优策略。',
       '<b>B：错误。</b> 经典完整回合 MC 要等回合结束，得到回报后才能学习。',
       '<b>C：需加条件。</b> 抽样避免了枚举全部后继转移，可能减少计算，但样本方差、回合长度和采样成本都影响效率，不能保证比 DP 更快。',
       '<b>D：基本正确。</b> 样本均值估计期望的依据是大数定律；仍需固定评估目标、足够访问和适当的可积性等条件。'),
    '完整回报、自举与持续任务',p('MC 使用完整回报作为目标，不自举；TD 用 Rₜ₊₁ + γV(Sₜ₊₁) 作为目标，依赖已有价值估计，可以不等回合结束就更新。') +
    p('无限折扣回报在数学上可能存在，但有限计算无法直接观察其无限尾部。人为截断会遗漏尾部；若追加估计价值，就引入了自举。应区分这些变体与本题的经典完整回合 MC。非马尔可夫观测下，估计还可能取决于历史分布；加入历史、记忆或信念状态有助于决策。')),
    (4,2,'蒙特卡洛策略迭代是否有模型','蒙特卡洛策略迭代是一种有模型强化学习方法。',['对','错'],1,
    p('答案为 B，错。经典蒙特卡洛策略迭代属于无模型（model-free）方法：它从状态、动作、奖励序列估计价值，不要求知道完整的转移概率 P(s′|s,a) 与奖励模型。') +
    f('按当前策略采集完整回合 → 用回报估计 Q<sup>π</sup>(s,a) → 改进策略 → 继续采样') +
    p('它保留了作业 3 中“评估 + 提升”的结构，但把使用已知模型的精确或迭代评估，换成了基于采样回报的估计。为避免过早停止探索，通常采用探索性起步或 ε-soft / ε-greedy 策略。'),
    '为什么无模型控制常估计 Q？',p('只知道 V(s)，一般还需要转移模型才能比较执行不同动作后的期望结果。直接估计 Q(s,a)，则可以通过比较动作价值来改进策略，无须显式计算转移分布。') +
    p('从模拟器取得经验，不会自动把算法变成需要显式环境模型的 DP。模拟器可以只提供样本；如果整体系统先学习模型，再用模型生成经验规划，则整个系统又可属于基于模型的方法。应区分经验来源与学习算法依赖的信息。')),
    (4,3,'蒙特卡洛方法的求解方式','蒙特卡洛方法是一种通过什么方式求解强化学习问题的方法？',
    ['通过动态规划求解','通过模拟经验求解','通过最优控制理论求解','通过随机梯度下降求解'],1,
    p('四个选项中应选 B，通过模拟经验求解。更完整的表述是：从真实交互或模拟交互产生的经验序列中，利用回报样本的平均值估计价值，并据此改进策略。模拟经验并不是唯一来源。') +
    f('S<sub>0</sub>, A<sub>0</sub>, R<sub>1</sub>, S<sub>1</sub>, …, S<sub>T</sub> → 计算 G<sub>t</sub> → 更新 V 或 Q') +
    p('例如固定策略下，某状态首次访问后的三个回报为 2、4、6，则当前 MC 均值估计为 (2 + 4 + 6)/3 = 4。样本增加后，在适当条件下估计更稳定。') +
    ul('A：动态规划利用已知模型进行期望备份，与采样完整回报的 MC 不同。',
       'C：最优控制是相关理论领域，并非本题所问的 MC 具体经验估计方式。',
       'D：随机梯度下降是优化工具，可以用于拟合 MC 回报目标，但不是 MC 方法的定义；表格型均值估计不需要神经网络。'),
    '增量平均：不用保存所有历史回报',f('N(s) ← N(s) + 1<br>V(s) ← V(s) + [G − V(s)] / N(s)') +
    p('该增量更新与样本算术平均等价。若将 1/N(s) 换为常数步长 α，则得到更偏重近期样本的估计，适合跟踪变化中的目标，但不再是全部历史样本的等权平均。') +
    p('经典 MC 的目标是一整段回报，不是把每一步奖励直接当作价值。长回合的回报可能方差较大，需要足够样本；“不需要模型”不等于“不需要数据”。')),
    (4,4,'每次访问 MC 的更新次数','在使用每次蒙特卡洛方法更新值函数时，如果一个状态在回合中被访问 2 次，那么它的值函数会被更新几次？',
    ['0','1','2','3'],2,
    p('答案为 C，2 次。“每次蒙特卡洛”指每次访问蒙特卡洛（every-visit MC），不是首次访问（first-visit MC）。它把回合内每次访问之后的回报都计入估计；访问 2 次就使用 2 个回报样本。') +
    f('S<sub>0</sub>=s ── R<sub>1</sub>=1 → S<sub>1</sub>=x ── R<sub>2</sub>=2 → S<sub>2</sub>=s ── R<sub>3</sub>=3 → 终止') +
    p('取 γ = 1，则第一次访问 s 后的回报 G₀ = 1 + 2 + 3 = 6，第二次访问后的回报 G₂ = 3。若此前没有样本，按访问时间顺序逐条纳入：') +
    f('第 1 个样本：N(s)=1，V(s)=6<br>第 2 个样本：N(s)=2，V(s)=6+(3−6)/2=4.5') +
    '<table><caption>同一回合内访问 s 两次</caption><thead><tr><th>方法</th><th>采用的回报</th><th>样本数</th></tr></thead><tbody><tr><td>首次访问 MC</td><td>只采用首次访问后的 6</td><td>1</td></tr><tr><td>每次访问 MC</td><td>采用 6 和 3</td><td>2</td></tr></tbody></table>',
    '样本贡献次数不等于程序赋值次数',p('本题按教材逐次增量更新的语境计为 2 次。程序也可以先收集两个回报，最后一次性重算均值；这时只有一次赋值语句，但统计意义上仍包含两次访问的样本。') +
    p('这些更新通常在回合结束后进行，并非访问时就知道完整回报。同一回合内的回报相互重叠，不能把两个样本当作独立回合。若倒序遍历回合实现首次访问 MC，应检查该状态在更早时刻是否出现，不能误把“倒序第一个”当作时间上的首次访问。')),
    (4,5,'ε-贪心策略的实现','ε-贪心策略是强化学习中一种重要的探索与利用平衡策略，其中 ε 是探索概率。以下哪个选项描述了 ε-贪心策略的实现方式？',
    ['在每个状态下，随机选择一个动作执行','按照预先定义好的动作顺序执行','根据当前状态值函数选择动作','以概率 ε 随机选择动作，以概率 1−ε 选择当前最优动作'],3,
    p('答案为 D。标准 ε-greedy 以概率 ε 从所有可选动作中均匀抽样，以概率 1−ε 选择当前估计价值最大的动作。前者探索，后者利用。这里“当前最优”指当前估计下的贪心动作，不保证是真实最优动作。') +
    f('a* ∈ arg max<sub>a</sub> Q(s,a)<br>唯一贪心动作：π(a*|s) = 1−ε+ε/n<br>任一非贪心动作：π(a|s) = ε/n') +
    p('随机探索仍然可能选中贪心动作，因此探索概率不是“选择非贪心动作的总概率”。例如 ε = 0.2、n = 4 时，贪心动作概率 0.85，每个非贪心动作概率 0.05；这与作业 1 第 5 题的计算规则一致。') +
    ul('A：始终随机，未体现一般 ε-greedy 的利用部分，仅对应 ε = 1 的特殊情况。',
       'B：固定顺序不体现按价值利用与随机探索的混合。',
       'C：未体现 ε 探索；而且单个状态价值 V(s) 本身不能区分该状态下的动作，一般需要 Q(s,a) 或结合模型做一步前瞻。'),
    '固定 ε、ε-soft 与 GLIE',p('ε &gt; 0 时，每个动作至少获得 ε/n 的选择概率，属于 ε-soft 策略。这能保留动作探索机会，但不能单凭固定 ε 就保证所有状态都被充分访问。') +
    p('固定 ε 的行为策略持续探索，一般不等于完全贪心最优策略。若希望逐渐转向贪心，同时仍保证充分探索，可研究 GLIE（无限探索、极限贪心）条件；仅写“ε 随时间减小”并不足以证明收敛，下降过快可能探索不足。若多个动作并列最优，还应明确并列动作的选择规则。')),
    ]

RECAP = '''<section id="mc-recap"><div class="eyebrow">MONTE CARLO / 复习卡</div><h2>从模型备份到经验回报</h2><div class="concepts"><p><b>MC 策略评估</b><br>完整回合 → 回报 → 均值估计</p><p><b>Every-visit MC</b><br>每次访问都提供一个回报样本</p><p><b>ε-greedy</b><br>随机探索 + 当前估计下的贪心利用</p></div><table><caption>DP、MC 与 TD 的典型区别</caption><thead><tr><th>方法</th><th>更新目标</th><th>显式模型</th><th>等待回合结束</th></tr></thead><tbody><tr><td>DP 策略评估</td><td>模型下的一步奖励与后继价值的期望</td><td>需要</td><td>不需要采集回合</td></tr><tr><td>经典 MC</td><td>完整采样回报 Gₜ</td><td>不需要</td><td>需要</td></tr><tr><td>TD(0)</td><td>Rₜ₊₁ + γV(Sₜ₊₁)</td><td>不需要</td><td>不需要</td></tr></tbody></table><p>DP 与 TD 使用已有价值进行自举，MC 不自举。终止转移中的下一状态价值通常取 0。MC 与 DP 的效率需要结合任务与计算成本比较。</p><table><caption>作业 4 · 易考判断</caption><thead><tr><th>说法</th><th>判断</th></tr></thead><tbody><tr><td>经典完整回合 MC 不要求回合结束</td><td>错</td></tr><tr><td>MC 策略迭代必须知道转移概率</td><td>错</td></tr><tr><td>MC 可使用真实经验或模拟经验</td><td>对</td></tr><tr><td>每次访问 MC 中，访问两次就纳入两个回报样本</td><td>对</td></tr><tr><td>首次访问 MC 只统计一个回合中的首次访问</td><td>对；不是整个训练过程仅统计一次</td></tr><tr><td>MC 抽样，因此一定比 DP 快</td><td>错；没有这种保证</td></tr><tr><td>ε-greedy 探索时不可能选中贪心动作</td><td>错</td></tr><tr><td>当前贪心动作必然是真实最优动作</td><td>错；价值估计可能不准确</td></tr></tbody></table><p>题目来源：用户提供的五张截图，选项按截图顺序标记 A–D（判断题为 A 对、B 错）。答案与解析为本次独立解答，不是官方答案。课程核对：本地《4 蒙特卡洛学习》第 4–8、15 页。延伸阅读：<a href="https://www.incompleteideas.net/book/bookdraft2018mar21.pdf">Sutton &amp; Barto，第 5 章 Monte Carlo Methods</a>；ε-greedy 参见第 2 章。</p></section>'''
